import { createCn } from "cn/config"

// Class merging that knows Serigraph's theme. Without this, cn reads `text-small` or `text-lead` as a text colour and
// drops it when a colour class such as `text-ink` follows; the same goes for the φ spacing names and the faces.
// Every kit component imports cn from here, not from "cn".
export const cn = createCn({
  extend: {
    theme: {
      text: ["small", "body", "lead", "h2", "h1", "title", "display"],
      leading: ["small", "body", "lead", "h2", "h1", "title", "display", "ui"],
      spacing: [
        "hair",
        "tight",
        "snug",
        "line",
        "section",
        "page",
        "control",
        "control-compact",
      ],
      font: ["read", "sans", "mono"],
      radius: ["plane", "box"],
    },
  },
})

/* Page-level defaults: the paper mat, the reading voice, links, focus and the accessibility fallbacks. */

/* The printed grain: four neutral layers at tile sizes that share no factors, so the grain never visibly repeats.
   Surfaces lay it over their colour, under their content; data-grain="off" takes it away. */
:root {
  --grain:
    var(--tex-specks), var(--tex-flecks), var(--tex-tooth), var(--tex-mottle);
  --grain-size: 541px, 613px, 353px, 1201px;
}
:root[data-grain="off"] {
  --grain: none;
}

@layer base {
  html {
    -webkit-text-size-adjust: 100%;
    text-size-adjust: 100%;
    background-color: var(--paper);
    color: var(--ink);
  }

  body {
    margin: 0;
    background-color: var(--paper);
    background-image: var(--grain);
    background-size: var(--grain-size);
    font-family: var(--face-read);
    font-size: var(--type-body);
    line-height: var(--lh-body);
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
  }

  h1,
  h2,
  h3,
  h4 {
    font-family: var(--face-sans);
    font-weight: 750;
    text-wrap: balance;
  }

  p,
  li {
    text-wrap: pretty;
  }

  a {
    color: inherit;
    text-decoration-line: underline;
    text-decoration-thickness: var(--line);
    text-underline-offset: 0.22em;
  }

  /* Focus: a second ring outside the first, with a gap of whatever lies beneath. */
  :focus-visible {
    outline: var(--line) solid var(--edge, var(--ink));
    outline-offset: 3px;
  }

  ::selection {
    background: var(--highlight);
    color: var(--ink);
  }
}

@media (forced-colors: active) {
  :root {
    --grain: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* Colourways: the same print with its colours rotated. Each assigns the spots to roles; paper and ink never change.
   Any element can carry data-colourway, so a page can show several. Sky is the default. */

:root,
[data-colourway="sky"] {
  --canvas: var(--sky);
  --plane: var(--bubblegum);
  --plane-2: var(--marigold);
  --action: var(--coral);
  --highlight: var(--seafoam);
  --cloud: var(--marigold);
  --tone-1: var(--bubblegum);
  --tone-2: var(--marigold);
  --tone-3: var(--seafoam);
  --tone-4: var(--lilac);
  /* Drawing roles (Follies). */
  --structure: var(--coral);
  --stair: var(--marigold);
  --platform: var(--seafoam);
  --sun: var(--coral);
  --bloom: var(--bubblegum);
  --leaf: var(--seafoam);
}

[data-colourway="pistachio"] {
  --canvas: var(--pistachio);
  --plane: var(--bubblegum);
  --plane-2: var(--seafoam);
  --action: var(--coral);
  --highlight: var(--marigold);
  --cloud: var(--bubblegum);
  --tone-1: var(--bubblegum);
  --tone-2: var(--seafoam);
  --tone-3: var(--marigold);
  --tone-4: var(--lilac);
  --structure: var(--coral);
  --stair: var(--bubblegum);
  --platform: var(--seafoam);
  --sun: var(--coral);
  --bloom: var(--coral);
  --leaf: var(--seafoam);
}

[data-colourway="coral"] {
  --canvas: var(--coral);
  --plane: var(--marigold);
  --plane-2: var(--bubblegum);
  --action: var(--sky);
  --highlight: var(--cornflower);
  --cloud: var(--marigold);
  --tone-1: var(--marigold);
  --tone-2: var(--bubblegum);
  --tone-3: var(--cornflower);
  --tone-4: var(--seafoam);
  --structure: var(--cornflower);
  --stair: var(--marigold);
  --platform: var(--bubblegum);
  --sun: var(--sky);
  --bloom: var(--bubblegum);
  --leaf: var(--seafoam);
}

[data-colourway="marigold"] {
  --canvas: var(--marigold);
  --plane: var(--lilac);
  --plane-2: var(--bubblegum);
  --action: var(--coral);
  --highlight: var(--seafoam);
  --cloud: var(--bubblegum);
  --tone-1: var(--lilac);
  --tone-2: var(--bubblegum);
  --tone-3: var(--seafoam);
  --tone-4: var(--cornflower);
  --structure: var(--coral);
  --stair: var(--lilac);
  --platform: var(--cornflower);
  --sun: var(--coral);
  --bloom: var(--lilac);
  --leaf: var(--pistachio);
}

/* Night: the poster printed on a dark card. Text placed on the canvas turns paper; planes stay bright with ink. */
[data-colourway="night"] {
  --canvas: var(--prussian);
  --plane: var(--lilac);
  --plane-2: var(--cornflower);
  --action: var(--marigold);
  --highlight: var(--bubblegum);
  --cloud: var(--lilac);
  --tone-1: var(--lilac);
  --tone-2: var(--cornflower);
  --tone-3: var(--bubblegum);
  --tone-4: var(--seafoam);
  --structure: var(--coral);
  --stair: var(--marigold);
  --platform: var(--seafoam);
  --sun: var(--marigold);
  --bloom: var(--bubblegum);
  --leaf: var(--seafoam);
}

/* Derived roles, recomputed wherever a colourway is set. Mixed in OKLab, flat: nothing is translucent. */
:root,
[data-colourway] {
  --on-canvas: var(--ink);
  --walk: color-mix(in oklab, var(--structure) 42%, var(--paper));
  --structure-shade: color-mix(in oklab, var(--structure) 88%, var(--ink));
}
[data-colourway="night"] {
  --on-canvas: var(--paper);
}

/* Follies on the page: a drawing fills its box and carries the same printed grain as the surfaces around it, laid
   over the art (never over text). Size the box with CSS; scenes slice from the bottom, marks are fitted whole. */
@utility folly {
  position: relative;
  display: block;
  & > svg {
    display: block;
    width: 100%;
    height: 100%;
  }
  &::after {
    content: "";
    position: absolute;
    inset: 0;
    background-image: var(--grain);
    background-size: var(--grain-size);
    pointer-events: none;
  }
}

/* An arch-topped frame for a window folly: round head, small bottom radii, a fine line. Set the width; the head
   stays a half circle at an aspect ratio of 3:4. */
@utility arch-frame {
  aspect-ratio: 3 / 4;
  overflow: hidden;
  border: var(--line) solid var(--ink);
  border-radius: 50% 50% var(--r-box) var(--r-box) / 37.5% 37.5% var(--r-box)
    var(--r-box);
  background: var(--canvas);
  --text: var(--on-canvas);
}

/* A motif sits beside text: an em tall by default, its box shaped to the motif. Set its height (or font-size) to size
   it and --motif to recolour it. No grain overlay: the motif's box is mostly the surface behind it. */
@utility motif {
  display: inline-block;
  block-size: 1em;
  aspect-ratio: 1;
  vertical-align: -0.15em;
  & > svg {
    display: block;
    width: 100%;
    height: 100%;
    overflow: visible;
  }
  &[data-motif="cloud"] {
    aspect-ratio: 5 / 2;
  }
  &[data-motif="archway"] {
    aspect-ratio: 100 / 124;
  }
}

/* The reading face until Serigraph Sans has a lowercase: Archivo, under the SIL Open Font License (shipped with the
   package). Its width axis (62–125%) is there for wider settings. Serigraph's own faces are in letters.generated.css. */
@import "@fontsource-variable/archivo/standard.css";

/* Display lettering: Serigraph Display in paper with an ink outline, and Serigraph Display Inline over it in ink, as
   on the poster's title. The outline is a text stroke painted under the fill, so half of it shows: outside each
   letter and inside its counters. It thickens a little with size (1.1% of the em) and never thins below the line. */
@utility lettering {
  position: relative;
  display: inline-block;
  font-family: var(--face-display);
  font-weight: 400;
  font-stretch: normal;
  letter-spacing: 0;
  line-height: var(--lh-display);
  color: var(--paper);
  -webkit-text-stroke: calc(2 * max(var(--line), 0.011em)) var(--ink);
  paint-order: stroke fill;
}

/* The inline: the same text in the Inline face, laid exactly over the letters. */
@utility lettering-inline {
  position: absolute;
  inset: 0;
  font-family: var(--face-display-inline);
  color: var(--ink);
  -webkit-text-stroke: 0;
  pointer-events: none;
  user-select: none;
}

/* Solid display lettering in one colour, for small sizes or a stamp. */
@utility lettering-solid {
  font-family: var(--face-display);
  font-weight: 400;
  line-height: var(--lh-display);
}

/* Generated by tools/fonts/build.mjs from the skeleton alphabet in src/serigraph/letters. Rerun it after a change. */
@font-face {
  font-family: "Serigraph Display";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(data:font/woff2;base64,) format("woff2");
}

@font-face {
  font-family: "Serigraph Display Inline";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(data:font/woff2;base64,) format("woff2");
}

@font-face {
  font-family: "Serigraph Sans";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(data:font/woff2;base64,) format("woff2");
}

@font-face {
  font-family: "Serigraph Sans";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url(data:font/woff2;base64,) format("woff2");
}

@font-face {
  font-family: "Serigraph Mono";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(data:font/woff2;base64,) format("woff2");
}

/* shadcn's semantic roles, mapped from the colourway's roles so shadcn-shaped code works unchanged. Ink is every
   border, input and ring, and the text on every bright surface. Charts take the action colour and the four tones,
   and tell series apart by fill (flat, stipple, louvers) as well as by colour. */

:root,
[data-colourway] {
  --background: var(--canvas);
  --foreground: var(--on-canvas);
  --card: var(--plane);
  --card-foreground: var(--ink);
  --popover: var(--plane);
  --popover-foreground: var(--ink);
  --primary: var(--action);
  --primary-foreground: var(--ink);
  --secondary: var(--plane-2);
  --secondary-foreground: var(--ink);
  --muted: color-mix(in oklab, var(--canvas) 30%, var(--paper));
  --muted-foreground: var(--ink);
  --accent: var(--highlight);
  --accent-foreground: var(--ink);
  --destructive: var(--rose);
  --border: var(--ink);
  --input: var(--ink);
  --ring: var(--ink);
  --chart-1: var(--action);
  --chart-2: var(--tone-1);
  --chart-3: var(--tone-2);
  --chart-4: var(--tone-3);
  --chart-5: var(--tone-4);
  --sidebar: var(--plane);
  --sidebar-foreground: var(--ink);
  --sidebar-primary: var(--action);
  --sidebar-primary-foreground: var(--ink);
  --sidebar-accent: var(--highlight);
  --sidebar-accent-foreground: var(--ink);
  --sidebar-border: var(--ink);
  --sidebar-ring: var(--ink);
  --radius: var(--r-box);
}

/* Serigraph: the Tailwind entry. Import this file once; it brings Tailwind, the faces, the tokens, the colourways,
   the grain and the surfaces. */
@import "tailwindcss";
@import "./fonts.css";
@import "./letters.generated.css";
@import "./lettering.css";
@import "./follies.css";
@import "./tokens.css";
@import "./colourways.css";
@import "./textures.generated.css";
@import "./roles.css";
@import "./base.css";
@import "./surfaces.css";

/* Night is a colourway; it also answers shadcn's dark variant, so parts that read it work. */
@custom-variant night (&:where([data-colourway="night"], [data-colourway="night"] *));
@custom-variant dark (&:where([data-colourway="night"], [data-colourway="night"] *));

@theme inline {
  --default-font-family: var(--face-read);
  --font-read: var(--face-read);
  --font-sans: var(--face-sans);
  --font-mono: var(--face-mono);
  --font-display: var(--face-display);

  --text-small: var(--type-small);
  --text-body: var(--type-body);
  --text-lead: var(--type-lead);
  --text-h2: var(--type-h2);
  --text-h1: var(--type-h1);
  --text-title: var(--type-title);
  --text-display: var(--type-display);

  --leading-small: var(--lh-small);
  --leading-body: var(--lh-body);
  --leading-lead: var(--lh-lead);
  --leading-h2: var(--lh-h2);
  --leading-h1: var(--lh-h1);
  --leading-title: var(--lh-title);
  --leading-display: var(--lh-display);
  --leading-ui: var(--lh-ui);

  --spacing-hair: var(--space-hair);
  --spacing-tight: var(--space-tight);
  --spacing-snug: var(--space-snug);
  --spacing-line: var(--space-line);
  --spacing-section: var(--space-section);
  --spacing-page: var(--space-page);
  --spacing-control: var(--control-height);
  --spacing-control-compact: var(--control-height-compact);
  --container-measure: var(--measure);

  --radius-plane: var(--r-plane);
  --radius-box: var(--r-box);

  --color-paper: var(--paper);
  --color-ink: var(--ink);
  --color-ink-quiet: var(--ink-quiet);
  --color-sky: var(--sky);
  --color-cornflower: var(--cornflower);
  --color-seafoam: var(--seafoam);
  --color-pistachio: var(--pistachio);
  --color-marigold: var(--marigold);
  --color-coral: var(--coral);
  --color-bubblegum: var(--bubblegum);
  --color-lilac: var(--lilac);
  --color-rose: var(--rose);
  --color-prussian: var(--prussian);

  --color-canvas: var(--canvas);
  --color-on-canvas: var(--on-canvas);
  --color-plane: var(--plane);
  --color-plane-2: var(--plane-2);
  --color-action: var(--action);
  --color-highlight: var(--highlight);
  --color-cloud: var(--cloud);
  --color-tone-1: var(--tone-1);
  --color-tone-2: var(--tone-2);
  --color-tone-3: var(--tone-3);
  --color-tone-4: var(--tone-4);

  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
}

/* Surfaces and the marks the style is built from. A surface decides the fill beneath its children (--surface),
   their text (--text) and their edges (--edge), so a field or an outline button sitting on it knows what to mix
   with. Flat colour, one fine line, grain under the content; nothing is shadowed, extruded or translucent. */

/* The poster: a paper mat (on in poster mode) around the canvas, which has a fine line and a big radius. */
@utility mat {
  padding: var(--mat);
}
@utility frame {
  border: var(--line) solid var(--ink);
  border-radius: var(--r-canvas);
  overflow: clip;
  :root[data-poster="off"] & {
    border: 0;
  }
}

@utility canvas {
  --surface: var(--canvas);
  --text: var(--on-canvas);
  --edge: var(--on-canvas);
  background-color: var(--canvas);
  background-image: var(--grain);
  background-size: var(--grain-size);
  color: var(--text);
}

/* Ground: a section in the cloud colour, which a cloud bank rising into it continues. */
@utility ground {
  --surface: var(--cloud);
  --text: var(--ink);
  --edge: var(--ink);
  background-color: var(--cloud);
  background-image: var(--grain);
  background-size: var(--grain-size);
  color: var(--ink);
}

/* Plane: a card or panel in its colourway colour, or one of the four tones (data-tone="1" … "4"). */
@utility plane {
  --tone: initial;
  --surface: var(--tone, var(--plane));
  --text: var(--ink);
  --edge: var(--ink);
  background-color: var(--surface);
  background-image: var(--grain);
  background-size: var(--grain-size);
  color: var(--ink);
  border: var(--line) solid var(--ink);
  border-radius: var(--r-plane);
}
.plane[data-tone="1"] {
  --tone: var(--tone-1);
}
.plane[data-tone="2"] {
  --tone: var(--tone-2);
}
.plane[data-tone="3"] {
  --tone: var(--tone-3);
}
.plane[data-tone="4"] {
  --tone: var(--tone-4);
}
.plane[data-tone="plane-2"] {
  --tone: var(--plane-2);
}

/* Field: a tint of the surface beneath, so cream stays rare. */
@utility field-fill {
  background-color: color-mix(
    in oklab,
    var(--surface, var(--canvas)) 30%,
    var(--paper)
  );
  color: var(--ink);
}

/* Pressed: the fill steps toward ink and prints flat, without grain, so ink text keeps 4.5:1 on every spot.
   Set --fill on the element. */
@utility pressed-shade {
  background-color: color-mix(
    in oklab,
    var(--fill, var(--surface)) 92%,
    var(--ink)
  );
  background-image: none;
}

/* Stipple: fine ink dots, for the shadow side of round forms and the dialog backdrop. */
@utility stipple {
  background-image: radial-gradient(
    circle,
    var(--ink) 0.6px,
    transparent 0.9px
  );
  background-size: 3px 3px;
}
@utility stipple-screen {
  background-image: radial-gradient(
    circle,
    var(--ink) 0.75px,
    transparent 1.05px
  );
  background-size: 4px 4px;
}

/* Louvers: thin slats of the action colour and ink, like a stair seen from below. */
@utility louvers {
  background-image: repeating-linear-gradient(
    to bottom,
    var(--action) 0 3px,
    var(--ink) 3px 5px
  );
}

/* The extended capitals, in Serigraph Sans: labels, navigation, buttons, kickers and metadata. */
@utility caps {
  font-family: var(--face-caps);
  font-weight: 700;
  font-size: var(--type-small);
  line-height: var(--lh-ui);
  letter-spacing: 0.1em;
}

/* A raised ordinal (15TH) and the round middle dot between details, as on the poster. */
@utility ord {
  font-size: 0.7em;
  letter-spacing: 0.06em;
  vertical-align: 0.62em;
  margin-left: 0.1em;
}
@utility sep {
  display: inline-block;
  margin-inline: 0.45em;
  transform: scale(0.8);
}

/* The concentric focus ring, for parts that draw their own focus. */
@utility focus-ring {
  outline: var(--line) solid var(--edge, var(--ink));
  outline-offset: 3px;
}

